// 만든 파일이다. 고치지 말고 tools/make_home_motion.py 를 다시 돌린다.
// 원본: client/design-refs/home-hero-motion.html (대표 확정 홈 배경). 소나무 흔들림, 구름, 빛줄기, 별, 빛 알갱이.
window.HomeMotion = {
  img: "data:image/webp;base64,",
  mask: "data:image/png;base64,",
  fs: `precision highp float;
uniform sampler2D img, msk;
uniform vec2 res;
uniform float asp, t;
uniform vec3 mp;
uniform float mr;
uniform float lg;
float hash(vec2 p){ return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453); }
float noise(vec2 p){
  vec2 i = floor(p), f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  return mix(mix(hash(i), hash(i + vec2(1.0, 0.0)), f.x), mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), f.x), f.y);
}
float fbm(vec2 p){ return 0.6 * noise(p) + 0.3 * noise(p * 2.03 + 7.1) + 0.1 * noise(p * 4.01 + 3.3); }
float lum(vec3 c){ return dot(c, vec3(0.2126, 0.7152, 0.0722)); }
void main(){
  vec2 uv = gl_FragCoord.xy / res;
  uv.y = 1.0 - uv.y;
  float ra = res.x / res.y;
  vec2 s = ra > asp ? vec2(1.0, asp / ra) : vec2(ra / asp, 1.0);
  uv = (uv - 0.5) * s + 0.5;
  vec2 sc = gl_FragCoord.xy / res;
  sc.y = 1.0 - sc.y;
  float near = 0.0, moon = 0.0;
  if (mp.z > 0.0) { float dq = length((sc - mp.xy) * vec2(ra, 1.0)); near = mp.z * (1.0 - smoothstep(0.0, 1.0, dq / max(mr * ra, 0.001))); moon = mp.z * (1.0 - smoothstep(0.35, 1.0, dq / (0.2 * ra))); }
  // 화면 전체가 아주 천천히 숨 쉬듯 커졌다 작아진다
  uv = (uv - 0.5) / (1.03 + 0.012 * sin(t * 0.13)) + 0.5;
  vec4 m = texture2D(msk, uv);
  vec3 first = texture2D(img, uv).rgb;
  // 소나무: 바람이 지나가듯 흔들린다
  float gust = 0.55 + 0.45 * sin(t * 0.37 + uv.x * 3.2 - uv.y * 1.4);
  vec2 sway = vec2(sin(uv.x * 7.0 + uv.y * 5.0 + t * 0.85) + 0.5 * sin(uv.x * 19.0 - uv.y * 13.0 + t * 1.75), 0.35 * sin(uv.x * 11.0 + uv.y * 9.0 + t * 1.1));
  vec2 off = m.r * gust * sway * 0.0017 * (1.0 + 1.2 * near);
  // 구름: 천천히 일렁이며 흐른다
  vec2 q = uv * vec2(5.0, 7.0);
  vec2 flow = vec2(fbm(q + vec2(t * 0.06, 0.0)), fbm(q + vec2(5.2, t * 0.05))) - 0.5;
  off += m.g * (flow * 0.02 + vec2(sin(t * 0.19 + uv.y * 6.0) * 0.005, 0.0));
  vec3 c = texture2D(img, uv + off).rgb;
  // 왼쪽 위에서 들어오는 빛줄기
  vec2 p = uv - vec2(-0.1, -0.02);
  p.y *= 941.0 / 1672.0;
  float a = atan(p.y, p.x), r = length(p);
  vec2 pm = (mp.xy - 0.5) * s + 0.5 - vec2(-0.1, -0.02);
  pm.y *= 941.0 / 1672.0;
  a -= mp.z * clamp(atan(pm.y, pm.x) - 0.44, -0.5, 0.5) * 0.3;
  float beam = pow(0.5 + 0.5 * sin(a * 42.0 + t * 0.21), 3.0) * 0.6 + pow(0.5 + 0.5 * sin(a * 97.0 - t * 0.33 + 1.7), 5.0) * 0.4;
  float win = smoothstep(0.12, 0.3, a) * (1.0 - smoothstep(0.52, 0.76, a));
  float shaft = beam * win * exp(-r * 1.15) * (0.5 + 0.15 * sin(t * 0.31)) * (1.0 + 0.9 * near) * lg;
  c += vec3(shaft + win * exp(-r * 2.0) * 0.14 * lg) * (1.0 - m.b);
  // 건물과 문양: 형태는 그대로 두고 빛만 지나간다
  float sweep = uv.x + uv.y * 0.5 - (mod(t * 0.11, 2.6) - 0.5);
  c += m.b * exp(-sweep * sweep * 90.0) * lum(c) * 0.9;
  if (near > 0.0) { float sheen = pow(0.5 + 0.5 * sin((sc.x * ra + sc.y) * 14.0 - t * 2.2), 4.0); c += c * m.b * near * (0.35 + 2.4 * sheen); }
  // 어두운 하늘의 별 반짝임
  vec2 g = uv * vec2(130.0, 73.0);
  vec2 id = floor(g);
  float h = hash(id);
  if (h > 0.9 - 0.16 * near) {
    float ex = step(h, 0.9);
    float tw = pow(max(0.0, sin(t * (0.5 + fract(h * 37.0) * 1.3) + h * 90.0)), 18.0);
    tw = mix(tw, 0.6 + 0.4 * fract(h * 53.0), near);
    float d = length(fract(g) - 0.5 - ex * (vec2(fract(h * 71.0), fract(h * 113.0)) - 0.5) * 0.56);
    c += vec3(smoothstep(0.24 - 0.08 * ex, 0.0, d) * tw) * (1.0 - smoothstep(0.1, 0.34, lum(first))) * 0.95 * (1.0 + 1.4 * near);
  }
  // 천천히 떠오르는 빛 알갱이
  for (float i = 1.0; i < 4.0; i += 1.0) {
    vec2 v = uv * vec2(9.0, 5.0) * (0.7 + i * 0.35) + vec2(sin(t * 0.13 + i) * 0.5 + i * 3.1, t * 0.05 * (0.6 + i * 0.3));
    vec2 cell = floor(v);
    float k = hash(cell + i * 11.0);
    if (k > 0.55) {
      vec2 ce = 0.5 + 0.35 * vec2(sin(k * 50.0), cos(k * 83.0));
      float d = length(fract(v) - ce);
      float fade = 0.5 + 0.5 * sin(t * (0.3 + k) + k * 40.0);
      c += vec3(smoothstep(0.075, 0.0, d)) * fade * 0.42 * (1.0 - m.b) * (1.0 + 2.5 * min(shaft * 2.0, 1.0));
    }
  }
  c *= 1.0 + 0.25 * moon;
  gl_FragColor = vec4(c, 1.0);
}
`
};
// 캔버스에 그린다. 그림을 다 읽으면 캔버스에 ready를 붙인다. active()가 거짓이면 그리지 않고 쉰다(보이지 않을 때 힘을 아낀다).
// mouse()가 있으면 그릴 때마다 [가로 0~1, 세로 0~1, 세기 0~1, 반지름(가로 비율)]을 받아 넘긴다(회사소개). 없으면 홈과 같다.
// 그리는 방법은 원본 home-hero-motion.html과 같다. cv.__draw(초)로 한 장을 그릴 수 있다(확인 도구용).
window.HomeMotion.start = function (cv, active, mouse) {
  var gl = cv.getContext('webgl', { antialias: false, alpha: false });
  if (!gl) return null;
  function sh(type, src) { var s = gl.createShader(type); gl.shaderSource(s, src); gl.compileShader(s); return s; }
  var pr = gl.createProgram();
  gl.attachShader(pr, sh(gl.VERTEX_SHADER, 'attribute vec2 a;void main(){gl_Position=vec4(a,0.0,1.0);}'));
  gl.attachShader(pr, sh(gl.FRAGMENT_SHADER, window.HomeMotion.fs));
  gl.bindAttribLocation(pr, 0, 'a');
  gl.linkProgram(pr);
  if (!gl.getProgramParameter(pr, gl.LINK_STATUS)) return null;
  gl.useProgram(pr);
  gl.bindBuffer(gl.ARRAY_BUFFER, gl.createBuffer());
  gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1, -1, 3, -1, -1, 3]), gl.STATIC_DRAW);
  gl.enableVertexAttribArray(0);
  gl.vertexAttribPointer(0, 2, gl.FLOAT, false, 0, 0);
  var U = function (n) { return gl.getUniformLocation(pr, n); };
  function tex(unit, src) {
    gl.activeTexture(gl.TEXTURE0 + unit);
    gl.bindTexture(gl.TEXTURE_2D, gl.createTexture());
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
    gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGB, gl.RGB, gl.UNSIGNED_BYTE, src);
  }
  var im = new Image(), mk = new Image();
  im.src = window.HomeMotion.img; mk.src = window.HomeMotion.mask;
  Promise.all([im.decode(), mk.decode()]).then(function () {
    tex(0, im); tex(1, mk);
    gl.uniform1i(U('img'), 0); gl.uniform1i(U('msk'), 1); gl.uniform1f(U('asp'), im.naturalWidth / im.naturalHeight);
    var ures = U('res'), ut = U('t'), ump = U('mp'), umr = U('mr');
    gl.uniform1f(U('lg'), cv.classList.contains('hero-gl') ? 1.7 : 1.0);
    function draw(sec) {
      var cw = cv.clientWidth, ch = cv.clientHeight;
      if (!cw || !ch) return;
      var r = Math.min(window.devicePixelRatio || 1, 1.5), w = Math.min(Math.round(cw * r), 2560), h = Math.round(w * ch / cw);
      if (cv.width !== w || cv.height !== h) { cv.width = w; cv.height = h; gl.viewport(0, 0, w, h); }
      var m = mouse ? mouse() : null;
      gl.uniform3f(ump, m ? m[0] : 0, m ? m[1] : 0, m ? m[2] : 0); gl.uniform1f(umr, m ? m[3] : 0);
      gl.uniform2f(ures, w, h); gl.uniform1f(ut, sec); gl.drawArrays(gl.TRIANGLES, 0, 3);
    }
    cv.__draw = draw;
    cv.classList.add('ready');
    draw(0);
    function loop(ms) { if (active()) draw(ms / 1000); requestAnimationFrame(loop); }
    requestAnimationFrame(loop);
  });
  return true;
};
